                                                                                                                  'markedly '
                                                                                                                  'low '
                                                                                                                  'in '
                                                                                                                  'most '
                                                                                                                  'PCD '
                                                                                                                  'patients, '
                                                                                                                  'in '
                                                                                                                  'children '
                                                                                                                  'old '
                                                                                                                  'enough '
                                                                                                                  'to '
                                                                                                                  'cooperate. '
                                                                                                                  'Confirm '
                                                                                                                  'with '
                                                                                                                  'genetic '
                                                                                                                  'testing, '
                                                                                                                  'electron '
                                                                                                                  'microscopy '
                                                                                                                  'of '
                                                                                                                  'ciliary '
                                                                                                                  'ultrastructure, '
                                                                                                                  'or '
                                                                                                                  'high-speed '
                                                                                                                  'video '
                                                                                                                  'microscopy '
                                                                                                                  'of '
