                                                                                                             'if '
                                                                                                             'not, '
                                                                                                             'the '
                                                                                                             'flap '
                                                                                                             'is '
                                                                                                             'lost. '
                                                                                                             'Alternatives '
                                                                                                             'include '
                                                                                                             'a '
                                                                                                             'pedicled '
                                                                                                             'inferior '
                                                                                                             'turbinate '
                                                                                                             'or '
                                                                                                             'middle '
                                                                                                             'turbinate '
                                                                                                             'flap, '
                                                                                                             'an '
