                                                                                                  'using '
                                                                                                  'backbiting '
                                                                                                  'forceps '
                                                                                                  'carefully '
                                                                                                  'on '
                                                                                                  'the '
                                                                                                  'residual '
                                                                                                  'uncinate. '
                                                                                                  'Injury '
