                                                                                                  'safer, '
                                                                                                  'though '
                                                                                                  'the '
                                                                                                  'orbital '
                                                                                                  'floor '
                                                                                                  'above '
                                                                                                  'and '
                                                                                                  'sphenopalatine '
                                                                                                  'artery '
                                                                                                  'branches '
